 var cc=L.choices.filter(function(c){return c[0]===L.correct})[0];var a1=el("p",null,"");a1.appendChild(el("strong",null,"Answer: "));a1.appendChild(document.createTextNode(cc[1]));rv.appendChild(a1);rv.appendChild(el("p","ok",L.ok));
 rv.appendChild(el("p",null,"Why the other choices are wrong:"));var u2=el("ul");L.choices.forEach(function(c){if(c[0]!==L.correct)u2.appendChild(el("li",null,c[0]+". "+c[1]+" → "+L.refs[c[0]]))});rv.appendChild(u2);sec.appendChild(rv);
